BEGIN;SET LOCAL statement_timeout='30s';
DO $$DECLARE native uuid;actor uuid;org uuid:=gen_random_uuid();req uuid:=gen_random_uuid();r jsonb;r2 jsonb;c tj.iq_cards%ROWTYPE;ch record;date1 timestamptz;bad text;snap uuid;day date:=(now() AT TIME ZONE 'America/Toronto')::date;
BEGIN
 SELECT target_user_id,source_user_id INTO native,actor FROM tj.source_user_identity_map i WHERE activation_status='activated' AND NOT EXISTS(SELECT 1 FROM tj.platform_admins a WHERE a.user_id=i.source_user_id) AND NOT EXISTS(SELECT 1 FROM tj.academy_progress p WHERE p.user_id=i.source_user_id) LIMIT 1;
 IF actor IS NULL THEN RAISE EXCEPTION 'fixture unavailable';END IF;
 INSERT INTO tj.organizations(id,name,slug) VALUES(org,'Rollback Academy records',org::text);
 INSERT INTO tj.organization_members(organization_id,user_id,role,status) VALUES(org,actor,'owner','active');
 INSERT INTO tj.org_app_entitlements(organization_id,app_key,status) VALUES(org,'iq_academy','active');
 SELECT * INTO c FROM tj.iq_cards WHERE card_type='quiz' AND jsonb_typeof(options)='array' AND options ? correct_option AND jsonb_array_length(options)>1 LIMIT 1;
 IF c.id IS NULL THEN RAISE EXCEPTION 'quiz fixture unavailable';END IF;
 SELECT v INTO bad FROM jsonb_array_elements_text(c.options) v WHERE v<>c.correct_option LIMIT 1;
 INSERT INTO tj.academy_daily_metrics(user_id,metric_date,touches,debrief) VALUES(actor,day,3,'Preserved evidence') ON CONFLICT(user_id,metric_date) DO UPDATE SET touches=3,debrief='Preserved evidence';
 PERFORM set_config('request.jwt.claim.sub',native::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.tj_runtime_academy_records(jsonb_build_object('action','daily_delta','field','touches','delta',1,'request_id',req));
 r2:=public.tj_runtime_academy_records(jsonb_build_object('action','daily_delta','field','touches','delta',1,'request_id',req));
 IF r<>r2 OR (r->'metrics'->>'touches')::int<>4 OR r->>'metric_date'<>day::text OR r->'metrics'->>'debrief'<>'Preserved evidence' THEN RAISE EXCEPTION 'Metric/date/idempotence/evidence failed';END IF;
 BEGIN PERFORM public.tj_runtime_academy_records(jsonb_build_object('action','daily_delta','field','debrief','delta',1,'request_id',gen_random_uuid()));RAISE EXCEPTION 'Invalid field accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.tj_runtime_academy_records(jsonb_build_object('action','daily_load','user_id',gen_random_uuid()));RAISE EXCEPTION 'Spoof accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 req:=gen_random_uuid();r:=public.tj_runtime_academy_records(jsonb_build_object('action','card_answer','card_id',c.id,'answer',bad,'request_id',req));r2:=public.tj_runtime_academy_records(jsonb_build_object('action','card_answer','card_id',c.id,'answer',bad,'request_id',req));IF r<>r2 OR r->>'correct'<>'false' THEN RAISE EXCEPTION 'Quiz grading/retry failed';END IF;
 r:=public.tj_runtime_academy_records(jsonb_build_object('action','card_answer','card_id',c.id,'answer',c.correct_option,'request_id',gen_random_uuid()));IF r->>'correct'<>'true' THEN RAISE EXCEPTION 'Correct answer not graded';END IF;
 FOR ch IN SELECT id FROM tj.academy_chapters WHERE chapter_number BETWEEN 1 AND 8 ORDER BY chapter_number LOOP PERFORM public.tj_runtime_academy_activity(jsonb_build_object('action','set_lesson','chapter_id',ch.id,'completed',true));END LOOP;
 r:=public.tj_runtime_academy_records('{"action":"tracks_load"}');SELECT (v->>'completed_at')::timestamptz INTO date1 FROM jsonb_array_elements(r->'tracks') v WHERE v->>'track_key'='foundation';IF date1 IS NULL THEN RAISE EXCEPTION 'Track failed to complete';END IF;
 EXECUTE 'RESET ROLE';
 IF NOT EXISTS(SELECT 1 FROM tj.academy_quiz_scores WHERE user_id=actor AND vol='deck:'||c.deck_id AND score=1 AND total=1) OR (SELECT count(*) FROM tj_private.academy_record_events WHERE source_user_id=actor AND kind='card_answer')<>2 THEN RAISE EXCEPTION 'Quiz aggregate/history failed';END IF;
 IF (tj_private.command_centre_academy_evidence(org)->'daily_five'->>'touches')::int<>4 THEN RAISE EXCEPTION 'Daily Five evidence missing';END IF;
 EXECUTE 'SET LOCAL ROLE authenticated';PERFORM public.tj_runtime_academy_activity(jsonb_build_object('action','set_lesson','chapter_id',ch.id,'completed',false));EXECUTE 'RESET ROLE';
 IF NOT EXISTS(SELECT 1 FROM tj.academy_track_progress WHERE user_id=actor AND track_key='foundation' AND completed_at IS NULL AND started_at IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM tj_private.academy_record_events WHERE source_user_id=actor AND kind='track_change' AND (payload->>'previous_completed_at')::timestamptz=date1 AND payload->>'completed_at' IS NULL) THEN RAISE EXCEPTION 'Unmark track/history failed';END IF;
 IF NOT EXISTS(SELECT 1 FROM tj_private.command_centre_refresh_queue WHERE organization_id=org) THEN RAISE EXCEPTION 'Reporting enqueue missing';END IF;
 snap:=tj_private.command_centre_rebuild(org,actor);IF NOT EXISTS(SELECT 1 FROM tj.executive_intelligence_snapshots WHERE id=snap AND (metrics->'training'->'daily_five'->>'touches')::int=4 AND (metrics->'training'->>'completed_tracks')::int=0) THEN RAISE EXCEPTION 'Snapshot publication failed';END IF;
 UPDATE tj.organization_members SET status='suspended' WHERE user_id=actor;EXECUTE 'SET LOCAL ROLE authenticated';BEGIN PERFORM public.tj_runtime_academy_records('{}');RAISE EXCEPTION 'Suspended access accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;EXECUTE 'RESET ROLE';
 IF has_function_privilege('anon','public.tj_runtime_academy_records(jsonb)','EXECUTE') OR has_table_privilege('authenticated','tj_private.academy_record_events','SELECT') THEN RAISE EXCEPTION 'Private access leak';END IF;
END $$;
SELECT jsonb_build_object('passed',true,'fixtures_persisted',0,'checks',jsonb_build_array('atomic bounded metric deltas','Toronto source day','retry idempotence','existing fields preserved','server quiz grading','latest per card aggregate','append-only attempts','track chapter requirements','unmark retains history','report queue','spoof and suspended denial','private permissions')) verification;
ROLLBACK;
